"""Pin existing TD undead MeshParts. Never modify TD or upload assets."""
from pathlib import Path
import xml.etree.ElementTree as E
import json, hashlib, subprocess
root=Path(__file__).resolve().parents[1];td=root.parent/'throne-defense'
out=root/'assets/shared/td-haunted-graveyard';out.mkdir(parents=True,exist_ok=True)
source=td/'assets/models/meshy-deepwood-slime-v1/runtime.rbxmx';raw=source.read_bytes()
names={'Zombie':'zombie','Skeleton':'skeleton','Ghoul':'ghoul','Mummy':'mummy','Hellhound':'hellhound','SkeletonKnight':'skeleton_knight','DeathKnight':'death_knight','Lich':'lich','LichSovereign':'lich_sovereign','DreadCommander':'dread_commander','Veyr':'dread_commander'}
folder=E.Element('Item',{'class':'Folder','referent':'HauntedGraveyardModels'});props=E.SubElement(folder,'Properties');E.SubElement(props,'string',{'name':'Name'}).text='HauntedGraveyardModels'
models={};rigs={};inserted=set()
for kind,name in names.items():
 model=next(m for m in E.fromstring(raw).findall('./Item/Item')if m.find('./Properties/string[@name="Name"]').text==name)
 assert not any(x.attrib.get('class')in ['Script','LocalScript','ModuleScript']for x in model.iter('Item'))
 parts=[m.find('./Properties/string[@name="Name"]').text for m in model.findall('./Item')if m.attrib['class']=='MeshPart']
 print(kind,parts)
 geompath=td/'assets/models/meshy-blocky-monsters-v1/runtime'/name/'geometry.json'
 geom=json.loads(geompath.read_text())
 models[kind]={'template':name,'parts':parts,'geometrySha256':hashlib.sha256(geompath.read_bytes()).hexdigest(),'triangles':geom['triangles'],'targetHeight':float(model.find('./Item[@class="NumberValue"]/Properties/double[@name="Value"]').text),'pivots':{p['name']:p['pivot']for p in geom['parts']},'role':'Veyr uses existing TD Dread Commander model'if kind=='Veyr'else 'existing TD undead model'}
 rigs[kind]={'template':name,'folder':'HauntedGraveyardModels','parts':parts}
 if name not in inserted:folder.append(model);inserted.add(name)
x=E.Element('roblox',{'version':'4'});x.append(folder);E.ElementTree(x).write(out/'runtime.rbxmx',encoding='utf-8',xml_declaration=True)
manifest={'version':1,'tdCommit':subprocess.check_output(['git','-C',str(td),'rev-parse','HEAD'],text=True).strip(),'sourcePath':str(source.relative_to(td)),'sourceSha256':hashlib.sha256(raw).hexdigest(),'runtimeSha256':hashlib.sha256((out/'runtime.rbxmx').read_bytes()).hexdigest(),'permission':'2026-11-03 explicit user request to reuse existing TD 3D models. Published RPG asset access remains to be tested.','models':models}
(out/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
lines=['-- Generated by tools/prepare-haunted-graveyard-assets.py; existing TD mesh IDs preserved.','return {']
for kind,s in rigs.items():lines.append(' '+kind+'={template='+json.dumps(s['template'])+',folder="HauntedGraveyardModels",parts={'+','.join(json.dumps(p)for p in s['parts'])+'}},')
lines+=['}'];(root/'src/shared/HauntedGraveyardRigs.luau').write_text('\n'.join(lines)+'\n')
for project in ['default.project.json','battle.project.json']:
 p=root/project;d=json.loads(p.read_text());d['tree']['ServerStorage']['HauntedGraveyardModels']={'$path':'assets/shared/td-haunted-graveyard/runtime.rbxmx'};p.write_text(json.dumps(d,indent=2)+'\n')
